\label{Thm-lie}



A w.c.m. manifold
$M^{3}(\varphi,Q,\xi,\eta,g)$, satisfying conditions \eqref{E-nS-10} and

\eqref{E-k-mu-nullity} with $\kappa<1$,
is locally isometric to one of the following unimodular Lie groups with a left-invariant metric:



$\bullet$
$SO(3)$ -- rotations about the origin of $\mathbb{R}^3$;

$\bullet$ $SL(2,\mathbb{R})$ -- linear transformations of $\mathbb{R}^2$ that preserve oriented area;


$\bullet$ $E(2)$ -- rigid motions of $\mathbb{R}^2$;

$\bullet$ $E(1,1)$ -- rigid motions of the Minkowski~plane.

\label{D-02}
\rm
A \textit{weak almost contact metric structure} on a differentiable connected manifold $M^{2n+1}$ is a set $(\varphi,Q,\xi$, $\eta,g)$, where $g$ is a Riemannian metric on $M$, $\varphi$ is a skew-symmetric (1,1)-tensor of rank $2n$, $\xi$ is a unit (Reeb) vector field, $\eta$ is a 1-form such that ${\eta}({\xi})=1$, satisfying
\begin{align}\label{2.2}
 & g({\varphi} X,{\varphi} Y)= g(X,Q\,Y)
 -{\eta}(X)\,{\eta}(Y)

 \qquad (X,Y\in\mathfrak{X}_M),
\end{align}
and $Q:=-{\varphi}^2 + {\eta}\otimes {\xi}$ is a self-adjoint (1,1)-tensor field

(and $Q=I$ for almost contact metric manifolds).
A~\textit{weak contact metric $($w.c.m.$)$ structure} is a weak almost contact metric structure satisfying
\begin{align}\label{2.2b}


 d\eta(X,Y)=g(X,\varphi Y).

\end{align}


A w.c.m. structure is called a \textit{weak $K$-contact structure} if the

vector field ${\xi}$ is Killing,~i.e., ${\cal L}_{\xi}\,g=0$.

\label{C-2cond}
Let a w.c.m. manifold satisfy the condition \eqref{Eq-2assump}, then $h$ is a self-adjoint traceless $(1,1)$-tensor that anti-commutes with $\varphi$ and commutes with $Q$; in addition,

$\nabla_{\xi}\,{Q}=\nabla_{\xi}\,\varphi=0$,
${\rm trace}\,h=0$,
and

\begin{equation}\label{E-xi-n}
 \nabla\,\xi = -\varphi - \varphi\,\widetilde h.
\end{equation}
A w.c.m. manifold

is weak K-contact if and only if, see \cite{rov-RS23},
\begin{equation}\label{E-xi-nK}
 \nabla\,\xi = -\varphi .
\end{equation}

\label{L-cond-equiv}
For a w.c.m.~manifold satisfying \eqref{Eq-2assump}, the property \eqref{E-1k-0-nullity} is equivalent to the following:

\begin{align}\label{E-nabla=phi-nullity}
 (\nabla_X\,\varphi)Y & = \eta(Y)\varphi^2X -g(X,\varphi^2Y)\xi .
\end{align}

If any of these conditions holds, then the structure is weak $K$-contact and

the equality is true,

\begin{align}\label{E-nS-10K}
 (\nabla_X Q)Y = \eta(Y)\widetilde Q \varphi X
 + g(\widetilde Q \varphi X, Y)\,\xi .
 \end{align}

\label{L-PRF-2}
For a weak $K$-contact manifold satisfying  \eqref{Eq-2assump},

the property \eqref{E-nabla=phi-nullity}
(and hence, \eqref{E-1k-0-nullity}, see Proposition~\ref{L-cond-equiv})
remains invariant under the PRF \eqref{E-GF-Rmix-Phi}.

For a w.c.m. manifold satisfying
\eqref{Eq-2assump}, the following is true:
\begin{align}\label{E-37}
 & QR_{\,\xi, X}\,\xi-\varphi R_{\,\xi,\,\varphi X}\,\xi
 = 2\,(h^2+Q\varphi^2) X.

\end{align}

Let's compute $R_{\xi\, X}\,\xi$ using \eqref{E-xi-n}
(where \eqref{Eq-2assump} is used)
together with $\nabla_{\xi}\,\xi=0$:

\begin{align}\label{E-38}
 R_{\xi, X}\,\xi
 & = -\nabla_\xi ( \varphi X +\varphi\,Q^{-1}hX)
 +\varphi[\xi,X] + \varphi\,Q^{-1}h\,[\xi,X].
\end{align}
Applying $\varphi$ to both sides of \eqref{E-38} and then recalling Proposition~\ref{C-2cond} and \eqref{E-xi-n}, we get
\begin{align*}
 \varphi R_{\,\xi, X}\,\xi
 &=-\varphi\nabla_\xi(\varphi X +\varphi\,Q^{-1}hX) +\varphi^2[\xi,X]+\varphi^2\,Q^{-1}h[\xi,X]\notag\\


 & = (\nabla_\xi\,h)X +Q\nabla_X\,\xi +h\nabla_X \xi
 -\eta((\nabla_\xi\,h)X)\xi -\eta(\nabla_X\,\xi)\xi
 -\eta(Q^{-1}h\nabla_X\,\xi).
\end{align*}
Using \eqref{E-xi-n} and the equality $\eta((\nabla_\xi\,h)X)=0$ (obtained by taking the covariant derivative of $g(hX,\xi)=0$ along $\xi)$ in the above equation, we get the relation
\begin{align}\label{E-36}
 (\nabla_{\xi}\,h)X=\varphi R_{\,\xi, X}\,\xi
 +Q\varphi X -\varphi\,Q^{-1}h^2X .
\end{align}

From \eqref{E-36} we get the following:
\begin{align*}
 QR_{\,\xi, X}\,\xi =-\varphi (\nabla_\xi\,h)X +Q\varphi^2X +h^2X,\quad

 \varphi R_{\,\xi, \varphi X}\,\xi =
 -\varphi(\nabla_\xi\,h)X-Q\varphi^2X-h^2X.
\end{align*}
The~combination of these two relations yields  \eqref{E-37}.
